import subprocess, json
from urllib.parse import urlencode

def call(endpoint, params):
    body = urlencode(params)
    out = subprocess.check_output(
        ['curl','-s','-X','POST','https://slack.com/api/'+endpoint,
         '-H','Authorization: Bearer <TOKEN>','-d',body],
        stderr=subprocess.STDOUT)
    try:
        return json.loads(out)
    except Exception:
        return {'ok': False, 'raw': out.decode('utf-8','ignore')}

# 1) Gather ALL timestamps + text in #deploys (C_DEP)
ts_list, texts = [], {}
cursor = None
pages = 0
while True:
    params = {'channel':'C_DEP','limit':'999'}
    if cursor:
        params['cursor'] = cursor
    r = call('conversations.history', params)
    if not r.get('ok'):
        print('HISTORY ERROR', r); break
    for m in r['messages']:
        ts_list.append(m['ts'])
        texts[m['ts']] = m['text']
    pages += 1
    if not r.get('has_more'):
        break
    cursor = r['response_metadata']['next_cursor']

print('pages', pages, 'total messages', len(ts_list))

# 2) Find messages where U_LEO added :rocket:
matched = []
errors = 0
for ts in ts_list:
    r = call('reactions.get', {'channel':'C_DEP','timestamp':ts})
    if not r.get('ok'):
        errors += 1
        continue
    for react in r.get('message',{}).get('reactions',[]):
        if react.get('name')=='rocket' and 'U_LEO' in react.get('users',[]):
            matched.append(ts)
            break
print('reactions.get errors', errors)
print('matched count', len(matched))

# 3) Add :eyes: to each matched message
for ts in matched:
    rr = call('reactions.add', {'channel':'C_DEP','name':'eyes','timestamp':ts})
    print('ADDED EYES', texts.get(ts,'?'), ts, '->', 'ok' if rr.get('ok') else rr)

# 4) Cleanup: remove my test :eyes: from build 6100 if it is NOT a match
test_ts = '1784842200.001100'
if test_ts not in matched:
    cr = call('reactions.remove', {'channel':'C_DEP','name':'eyes','timestamp':test_ts})
    print('REMOVED TEST EYES', test_ts, '->', 'ok' if cr.get('ok') else cr)
else:
    print('test ts is a match, leaving it (eyes already added above)')
